  "test_path": "tests/test_chat_message_render.py",
  "test": "import json

import pytest

from smolagents.models import (
    ChatMessage,
    ChatMessageToolCall,
    ChatMessageToolCallFunction,
    MessageRole,
)


def _make_tool():
    return ChatMessageToolCall(
        function=ChatMessageToolCallFunction(arguments={"x": 1}, name="my_tool"),
        id="1",
        type="tool-call",
    )


def test_render_as_markdown_with_content_and_tool():
    tool = _make_tool()
    msg = ChatMessage(role=MessageRole.USER, content="Hello", tool_calls=[tool])
    md = msg.render_as_markdown()
    # Should start with content then a newline before tool JSON
    assert md.startswith("Hello\n")
    expected = json.dumps({"tool": "my_tool", "arguments": {"x": 1}})
    assert md == "Hello\n" + expected


def test_render_as_markdown_tool_only():
    tool = _make_tool()
    msg = ChatMessage(role=MessageRole.USER, content=None, tool_calls=[tool])
    md = msg.render_as_markdown()
    expected = json.dumps({"tool": "my_tool", "arguments": {"x": 1}})
    assert md == expected
